#!/usr/bin/env bash
# PostToolUse hook (matcher: Edit|Write) — syntax-check the file that was just written.
#
# Exit codes for this event:
#   0  continue.
#   2  the tool already ran, so nothing is blocked, but Claude receives stderr
#      and can fix the file on its next step.
#
# Generated by tq-forge. Add a case below for other file types.

set -uo pipefail

input="$(cat)"

file_path="$(printf '%s' "$input" | python3 -c '
import json, sys
try:
    print(json.load(sys.stdin).get("tool_input", {}).get("file_path", ""))
except Exception:
    pass
' 2>/dev/null)"

[[ -n "$file_path" && -f "$file_path" ]] || exit 0

case "$file_path" in
    *.json)
        output="$(python3 -m json.tool -- "$file_path" 2>&1 >/dev/null)" ;;
    *.sh|*.bash)
        output="$(bash -n -- "$file_path" 2>&1)" ;;
    *.py)
        output="$(python3 -c 'import ast, sys
path = sys.argv[1]
ast.parse(open(path, encoding="utf-8").read(), path)' "$file_path" 2>&1)" ;;
    *.js|*.cjs|*.mjs)
        command -v node >/dev/null 2>&1 || exit 0
        output="$(node --check -- "$file_path" 2>&1)" ;;
    *)
        exit 0 ;;
esac
status=$?

if (( status != 0 )); then
    printf 'Syntax check failed for %s (from .claude/hooks/post-tool-use.sh):\n%s\n' \
        "$file_path" "$output" >&2
    exit 2
fi

exit 0
